view.template:
{% load view_tags %}
{% get_value 'project/title' as title %}
{% get_values 'project/research_field' as research_fields %}
{% get_value 'project/research_question/title' as research_question_title %}
{% get_set 'project/partner/id' as partners %}
{% get_values 'smp/software-license' as software_licenses %}

{# ############# #}
{# PROJECT TITLE #}
{# ############# #}
<h1>{{ title.value }}</h1>

{# ################# #}
{# RESEARCH FIELD(S) #}
{# ################# #}
{% if research_fields|length %}
    <p>This software belongs to the research field{{ research_fields|pluralize }}: {% if research_fields|length == 1 %}{{ research_fields.0.value }}
        {% elif research_fields|length > 1 %}
        <ul>
        {% for rf in research_fields %}
            <li>{{ rf.value }}</li>
        {% endfor %}
        </ul>
        {% endif %}
    </p>
{% endif %}

{# ######################################### #}
{# INTENDED USE AND CONTRIBUTION TO RESEARCH #}
{# ######################################### #}
{% if research_question_title and research_question_title.value != '' %}
    <p>Its intended use and its contribution to research:</p>
    <p>{{ research_question_title.value|linebreaks }}</p>
{% endif %}

{# ############## #}
{# CONTRIBUTOR(S) #}
{# ############## #}
{% if partners|length %}
    <p>Contributor{{ partners|pluralize }}:
    <ul>
    {% for p in partners %}
        {% with p_set_index_str=p.set_index|stringformat:'s' %}
        {% get_set_value p 'project/partner/type' as p_type %}
        {% get_set_value p 'project/partner/orcid' as p_orcid %}
        {% get_set_value p 'project/partner/website' as p_website %}
        {% get_set_value p 'project/partner/given-name' as p_given_name %}
        {% get_set_value p 'project/partner/family-name' as p_family_name %}
        {% get_set_value p 'project/partner/name' as p_name %}
        {% get_values 'project/partner/affiliation' p_set_index_str as p_affiliations %}
        {% get_values 'project/partner/role' p_set_index_str as p_roles %}
        <li>{% if p_type.option_uri == 'https://rdmo.mpdl.mpg.de/terms/options/partner-types/person' and p_given_name.value and p_family_name.value %}{{ p_given_name.value }} {{ p_family_name.value }}{% elif p_type.option_uri == 'https://rdmo.mpdl.mpg.de/terms/options/partner-types/entity' and p_name.value %}{{ p_name.value }}{% else %}{{ p.value }}{% endif %}{% if p_type.option_uri == 'https://rdmo.mpdl.mpg.de/terms/options/partner-types/person' and p_orcid.value %} ({{ p_orcid.value }}){% elif p_type.option_uri == 'https://rdmo.mpdl.mpg.de/terms/options/partner-types/entity' and p_website.value %} ({{ p_website.value }}){% endif %}{% if p_affiliations %}, {% for a in p_affiliations %}{% for r in p_roles %}{% if r.set_index == a.set_index %}{{ r.value }} at {% endif %}{% endfor %}{{ a.value }}{% if not forloop.last %} & {% endif %}{% endfor %}{% else %}{% if p_roles %}, {% for r in p_roles %}{{ r.value }}{% if not forloop.last %} & {% endif %}{% endfor %}{% endif %}{% endif %}</li>
        {% endwith %}
    {% endfor %}
    </ul>
    </p>
{% endif %}

{# ########## #}
{# LICENSE(S) #}
{# ########## #}
{% if software_licenses|length %}
    <p>Software license{{ software_licenses|pluralize }}: {% if software_licenses|length == 1 %}{% if software_licenses.0.text %}{{ software_licenses.0.text }}{% else %}{{ software_licenses.0.option_text }}{% endif %}
    {% elif software_licenses|length > 1 %}
    <ul>
        {% for sl in software_licenses %}
        <li>{% if sl.text %}{{ sl.text }}{% else %}{{ sl.option_text }}{% endif %}</li>
        {% endfor %}
    </ul>
    {% endif %}
    </p>
{% endif %}
